parameters.jsCode:
const items = $input.all();

function obterTexto(textos) {
  return (textos ?? [])
    .map(texto => texto.plain_text ?? texto.text?.content ?? '')
    .join('')
    .trim();
}

function possuiTaxonomia(pagina, nome) {
  return (pagina['🏷️ Taxonomias'] ?? []).some(taxonomia => {
    const nomeTaxonomia = obterTexto(
      taxonomia.properties?.Name?.title
    ).toLocaleLowerCase('pt-BR');

    return nomeTaxonomia === nome.toLocaleLowerCase('pt-BR');
  });
}

let resultadoEncontrado = null;
let tarefaEncontrada = items[0]?.json ?? {};

// Primeiro verifica as tarefas recebidas.
// Depois percorre os pais por nível de proximidade.
const fila = items.map(item => ({
  pagina: item.json,
  tarefaOriginal: item.json,
  visitados: new Set()
}));

for (let indice = 0; indice < fila.length; indice++) {
  const { pagina, tarefaOriginal, visitados } = fila[indice];

  if (!pagina) continue;

  const chave = pagina.id ?? pagina;

  if (visitados.has(chave)) continue;
  visitados.add(chave);

  const resultados = pagina['📦 Resultados'] ?? [];

  resultadoEncontrado = resultados.find(resultado =>
    possuiTaxonomia(resultado, 'post') &&
    possuiTaxonomia(resultado, 'linkedin')
  ) ?? null;

  if (resultadoEncontrado) {
    tarefaEncontrada = tarefaOriginal;
    break;
  }

  for (const pai of pagina['Item pai'] ?? []) {
    fila.push({
      pagina: pai,
      tarefaOriginal,
      visitados
    });
  }
}

// Fica vazio quando não houver Resultado.
const conteudo = obterTexto(
  resultadoEncontrado?.properties?.['Conteúdo']?.rich_text
);

// Busca a conta mesmo quando não houver Resultado.
const projetos = tarefaEncontrada['🎯 Projetos'] ?? [];

let contaLinkedIn = null;

for (const projeto of projetos) {
  const clientes = projeto['👥 Clientes'] ?? [];

  for (const cliente of clientes) {
    contaLinkedIn = (
      cliente['📇 Contas e Contatos'] ?? []
    ).find(conta =>
      possuiTaxonomia(conta, 'linkedin')
    ) ?? null;

    if (contaLinkedIn) break;
  }

  if (contaLinkedIn) break;
}

const organizationId = obterTexto(
  contaLinkedIn?.properties?.ID?.rich_text
) || null;

return [
  {
    json: {
      resultado: resultadoEncontrado,
      conteudo,
      organizationId
    }
  }
];

