parameters.jsCode:
const items = $input.all();

function obterTexto(textos) {
  return (textos ?? [])
    .map(texto => texto.plain_text ?? texto.text?.content ?? '')
    .join('')
    .trim();
}

function possuiTaxonomia(pagina, nome) {
  const nomeNormalizado = nome.toLocaleLowerCase('pt-BR');

  return (pagina['🏷️ Taxonomias'] ?? []).some(taxonomia => {
    const nomeTaxonomia = obterTexto(
      taxonomia.properties?.Name?.title
    ).toLocaleLowerCase('pt-BR');

    return nomeTaxonomia === nomeNormalizado;
  });
}

// Verifica se o resultado ainda não foi publicado.
function naoPublicado(resultado) {
  const propriedades = resultado.properties ?? {};

  const status = propriedades.Status?.status?.name ?? null;
  const url = propriedades.URL?.url ?? null;
  const data = propriedades.Data?.date ?? null;

  return (
    status !== 'Concluído' &&
    !url?.trim() &&
    !data
  );
}

// Verifica o conhecimento atual e seus descendentes.
function buscarResultado(conhecimentos, visitados = new Set()) {
  for (const conhecimento of conhecimentos) {
    if (!conhecimento) continue;

    const chave = conhecimento.id ?? conhecimento;

    if (visitados.has(chave)) continue;
    visitados.add(chave);

    const resultado = (
      conhecimento['📦 Resultados'] ?? []
    ).find(resultado =>
      possuiTaxonomia(resultado, 'post') &&
      possuiTaxonomia(resultado, 'linkedin') &&
      naoPublicado(resultado)
    );

    if (resultado) return resultado;

    const resultadoFilho = buscarResultado(
      conhecimento.Subitem ?? [],
      visitados
    );

    if (resultadoFilho) return resultadoFilho;
  }

  return null;
}

let resultadoEncontrado = null;

// Busca nos conhecimentos de cada projeto e seus subitens.
for (const item of items) {
  const projetos = item.json['🎯 Projetos'] ?? [];

  for (const projeto of projetos) {
    resultadoEncontrado = buscarResultado(
      projeto['📚 Conhecimentos'] ?? []
    );

    if (resultadoEncontrado) break;
  }

  if (resultadoEncontrado) break;
}

if (!resultadoEncontrado) {
  throw new Error(
    'Nenhum resultado pendente com as taxonomias "Post" e "LinkedIn" foi encontrado.'
  );
}

// Conteúdo obrigatório da publicação.
const conteudo = obterTexto(
  resultadoEncontrado.properties?.['Conteúdo']?.rich_text
);

if (!conteudo) {
  throw new Error(
    `O resultado "${resultadoEncontrado.id}" foi encontrado, mas a propriedade "Conteúdo" está vazia ou não foi recebida.`
  );
}

const organizationId =
  $('Buscar resultado na tarefa e nos ancestrais e identificar conta').first().json.organizationId || null;

return [
  {
    json: {
      resultado: resultadoEncontrado,
      conteudo,
      organizationId
    }
  }
];

