formula.expression:
if(
  empty(prop("Última execução")),
  prop("Início"),
  if(
    prop("Unidade de repetição") == "Dia",
    dateAdd(prop("Última execução"), prop("Intervalo"), "days"),

    if(
      prop("Unidade de repetição") == "Semana",
      lets(
        base, prop("Última execução"),

        proximos,
        [1, 2, 3, 4, 5, 6, 7]
          .map(
            lets(
              data, dateAdd(base, current, "days"),

              nomeDia,
              if(
                day(data) == 1, "Segunda",
                if(
                  day(data) == 2, "Terça",
                  if(
                    day(data) == 3, "Quarta",
                    if(
                      day(data) == 4, "Quinta",
                      if(
                        day(data) == 5, "Sexta",
                        if(
                          day(data) == 6,
                          "Sábado",
                          "Domingo"
                        )
                      )
                    )
                  )
                )
              ),

              if(
                prop("Dias da semana").includes(nomeDia),
                data,
                empty()
              )
            )
          )
          .filter(not empty(current)),

        proximos.first()
      ),

      if(
        prop("Unidade de repetição") == "Mês",
        dateAdd(prop("Última execução"), prop("Intervalo"), "months"),
        prop("Início")
      )
    )
  )
)
